import{_ as e,a as i,b as a,c as o}from"./chunks/state-monitoring-4.bYFhpwI8.js";import{_ as r,o as n,c as l,a5 as s}from"./chunks/framework.DGp912Ge.js";const R=JSON.parse('{"title":"상태 모니터링","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"ko/manual/gui/state-monitoring.md","filePath":"ko/manual/gui/state-monitoring.md","lastUpdated":1785806767000}'),g={name:"ko/manual/gui/state-monitoring.md"};function c(m,t,p,d,h,u){return n(),l("div",null,[...t[0]||(t[0]=[s('<h1 id="상태-모니터링" tabindex="-1">상태 모니터링 <a class="header-anchor" href="#상태-모니터링" aria-label="Permalink to &quot;상태 모니터링&quot;">​</a></h1><p>RBQGUI에서 로봇의 현재 상태(비상 정지/전원/센서/비전 모듈)를 실시간으로 확인합니다.</p><h2 id="_1-상단-상태-영역" tabindex="-1">1) 상단 상태 영역 <a class="header-anchor" href="#_1-상단-상태-영역" aria-label="Permalink to &quot;1) 상단 상태 영역&quot;">​</a></h2><p><code>EMERGENCY</code> 상태와 배터리/연결/전원 등 다양한 시스템 상태 아이콘을 한눈에 볼 수 있습니다.</p><figure style="margin-top:1rem;text-align:center;"><img src="'+e+'" alt="상단 상태 영역" style="display:block;margin:0 auto;"><figcaption style="text-align:center;margin-top:0.5rem;color:var(--vp-c-text-2, #666);font-size:0.95em;">상단 상태 영역</figcaption></figure><h2 id="_2-진단-테이블-모터-imu-등" tabindex="-1">2) 진단 테이블 (모터/IMU 등) <a class="header-anchor" href="#_2-진단-테이블-모터-imu-등" aria-label="Permalink to &quot;2) 진단 테이블 (모터/IMU 등)&quot;">​</a></h2><p>다리/관절(예: HRR/HRP/...)별 상태 값과 온도/자이로/가속도(ACC) 정보를 표로 확인합니다.</p><figure style="margin-top:1rem;text-align:center;"><img src="'+i+'" alt="진단 테이블" style="display:block;margin:0 auto;"><figcaption style="text-align:center;margin-top:0.5rem;color:var(--vp-c-text-2, #666);font-size:0.95em;">관절/센서 진단 테이블</figcaption></figure><h3 id="joint-naming-관절-id" tabindex="-1">Joint Naming (관절 ID) <a class="header-anchor" href="#joint-naming-관절-id" aria-label="Permalink to &quot;Joint Naming (관절 ID)&quot;">​</a></h3><p>진단 테이블의 관절 ID는 아래와 같습니다.</p><ul><li><strong>HRR</strong> : Hind Right Roll, <strong>HRP</strong> : Hind Right Pitch, <strong>HRK</strong> : Hind Right Knee</li><li><strong>HLR</strong> : Hind Left Roll, <strong>HLP</strong> : Hind Left Pitch, <strong>HLK</strong> : Hind Left Knee</li><li><strong>FRR</strong> : Front Right Roll, <strong>FRP</strong> : Front Right Pitch, <strong>FRK</strong> : Front Right Knee</li><li><strong>FLR</strong> : Front Left Roll, <strong>FLP</strong> : Front Left Pitch, <strong>FLK</strong> : Front Left Knee</li></ul><h2 id="_3-비전-perception-상태" tabindex="-1">3) 비전(Perception) 상태 <a class="header-anchor" href="#_3-비전-perception-상태" aria-label="Permalink to &quot;3) 비전(Perception) 상태&quot;">​</a></h2><p>IR 프로젝터, 나이트 비전, LED-버저 등 비전 관련 모듈의 ON/OFF와 각 모듈의 동작 상태, 오류, Fail/Count 정보를 확인합니다.</p><figure style="margin-top:1rem;text-align:center;"><img src="'+a+'" alt="비전 상태" style="display:block;margin:0 auto;"><figcaption style="text-align:center;margin-top:0.5rem;color:var(--vp-c-text-2, #666);font-size:0.95em;">비전 모듈 상태</figcaption></figure><h2 id="_4-전원-스위치-및-모듈-체크" tabindex="-1">4) 전원 스위치 및 모듈 체크 <a class="header-anchor" href="#_4-전원-스위치-및-모듈-체크" aria-label="Permalink to &quot;4) 전원 스위치 및 모듈 체크&quot;">​</a></h2><p>Vision Computer/카메라/센서(LiDAR 등)의 전원 스위치 상태와 BAT/LEGS/ADDON/EXTERN/CHARGE 등 주요 전원 및 부하 상태를 확인합니다. 버튼을 눌러 상태를 갱신합니다.</p><figure style="margin-top:1rem;text-align:center;"><img src="'+o+'" alt="전원 스위치 및 모듈 체크" style="display:block;margin:0 auto;"><figcaption style="text-align:center;margin-top:0.5rem;color:var(--vp-c-text-2, #666);font-size:0.95em;">전원 스위치 및 모듈 체크</figcaption></figure><h2 id="주의-사항" tabindex="-1">주의 사항 <a class="header-anchor" href="#주의-사항" aria-label="Permalink to &quot;주의 사항&quot;">​</a></h2><ul><li><strong>긴급 정지</strong> 또는 비정상 상태가 감지되면 먼저 안전을 확보한 후 원인(센서/전원/비전 모듈 동작 여부 등)을 확인하세요.</li><li>비전/센서 모듈이 OFF 상태이면 해당 기능(예: 비전 기반 보행)이 제한될 수 있습니다.</li></ul>',19)])])}const x=r(g,[["render",c]]);export{R as __pageData,x as default};
